# Disable Nagle Algorithm on All Network Adapters Write-Host "Disabling Nagle algorithm (TCP No Delay) on all adapters..." -ForegroundColor Cyan # Get all active network adapters $adapters = Get-NetAdapter | Where-Object { $_.Status -eq "Up" } foreach ($adapter in $adapters) { $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($adapter.InterfaceGuid)" if (Test-Path $regPath) { Set-ItemProperty -Path $regPath -Name "TcpAckFrequency" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path $regPath -Name "TCPNoDelay" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path $regPath -Name "TcpDelAckTicks" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host " Disabled Nagle on: $($adapter.Name)" -ForegroundColor Gray } else { Write-Host " Skipping: $($adapter.Name) (no registry entry)" -ForegroundColor DarkGray } } Write-Host "Nagle algorithm has been disabled on all active adapters." -ForegroundColor Green Write-Host "Reboot may be required for full effect." -ForegroundColor Yellow